mapper.update:
update erp_cut_order
set customer_id = #{customerId}, customer_name = #{customerName}, sales_order_id = #{salesOrderId},
    sales_order_no = #{salesOrderNo}, plan_finish_time = #{planFinishTime}, total_qty = #{totalQty},
    cut_status = #{cutStatus}, update_by = #{updateBy}, update_time = sysdate(), remark = #{remark}
where cut_order_id = #{cutOrderId}

update erp_cut_order
set cut_status = #{cutStatus}, finish_time = #{finishTime}, update_by = #{updateBy}, update_time = sysdate()
where cut_order_id = #{cutOrderId}

update erp_cut_order
set plan_finish_time = #{planFinishTime}, cut_status = 1, update_by = #{updateBy}, update_time = sysdate(), remark = #{remark}
where cut_order_id = #{cutOrderId}
  and cut_status in (0, 1)
